package pip

import (
	"sort"
	"testing"
)

func pkgMap(pkgs []pinnedPackage) map[string]string {
	m := make(map[string]string, len(pkgs))
	for _, p := range pkgs {
		m[p.name] = p.version
	}
	return m
}

func TestParsePoetryLock_ExtractsTransitiveClosure(t *testing.T) {
	// A realistic poetry.lock fragment: multiple packages, sub-tables
	// ([package.dependencies], [package.extras]) that must NOT leak their
	// own name/version-looking keys, and a trailing [metadata] table.
	const lock = `
# This file is automatically @generated by Poetry and should not be changed by hand.

[[package]]
name = "flask"
version = "2.0.1"
description = "A simple framework for building complex web applications."
optional = false
python-versions = ">=3.6"

[package.dependencies]
click = ">=7.1.2"
Werkzeug = ">=2.0"

[package.extras]
async = ["asgiref (>=3.2)"]

[[package]]
name = "werkzeug"
version = "2.0.3"
description = "The comprehensive WSGI web application library."

[[package]]
name = "jinja2"
version = "3.0.3"

[metadata]
lock-version = "1.1"
python-versions = "^3.8"
content-hash = "abc123"
`
	pkgs := parsePoetryLock(lock)
	got := pkgMap(pkgs)
	want := map[string]string{
		"flask":    "2.0.1",
		"werkzeug": "2.0.3",
		"jinja2":   "3.0.3",
	}
	if len(got) != len(want) {
		t.Fatalf("expected %d packages, got %d: %+v", len(want), len(got), pkgs)
	}
	for name, ver := range want {
		if got[name] != ver {
			t.Errorf("%s: want %s, got %s", name, ver, got[name])
		}
	}
	// The dependency-constraint keys inside [package.dependencies] (click,
	// Werkzeug as a >= constraint) must NOT appear as packages.
	if _, leaked := got["click"]; leaked {
		t.Error("a [package.dependencies] key leaked as a package")
	}
}

func TestParsePoetryLock_SkipsMalformedBlocks(t *testing.T) {
	const lock = `
[[package]]
name = "good"
version = "1.0.0"

[[package]]
name = "missing-version"

[[package]]
version = "2.0.0"
`
	pkgs := parsePoetryLock(lock)
	if len(pkgs) != 1 || pkgs[0].name != "good" || pkgs[0].version != "1.0.0" {
		t.Fatalf("only the complete block should parse, got %+v", pkgs)
	}
}

func TestParsePoetryLock_EmptyAndGarbage(t *testing.T) {
	for _, in := range []string{"", "not toml at all", "[[notpackage]]\nname=\"x\"\n"} {
		if pkgs := parsePoetryLock(in); len(pkgs) != 0 {
			t.Errorf("input %q should yield no packages, got %+v", in, pkgs)
		}
	}
}

func TestParsePoetryLock_HandlesV2StyleHeaders(t *testing.T) {
	// Poetry 1.5+ writes `[[package]]` identically but groups files under
	// [package.source] / [[package.files]] — ensure the files sub-array
	// doesn't break package detection.
	const lock = `
[[package]]
name = "requests"
version = "2.28.1"

[[package.files]]
file = "requests-2.28.1-py3-none-any.whl"
hash = "sha256:deadbeef"

[[package]]
name = "urllib3"
version = "1.26.12"
`
	got := pkgMap(parsePoetryLock(lock))
	if got["requests"] != "2.28.1" || got["urllib3"] != "1.26.12" {
		t.Fatalf("v2-style files sub-array broke parsing: %+v", got)
	}
	if len(got) != 2 {
		t.Errorf("expected exactly 2 packages, got %d: %+v", len(got), got)
	}
}

func TestParsePipfileLock_DefaultAndDevelop(t *testing.T) {
	const lock = `{
  "_meta": {"hash": {"sha256": "x"}},
  "default": {
    "flask": {"version": "==2.0.1", "hashes": ["sha256:a"]},
    "requests": {"version": "==2.28.1"}
  },
  "develop": {
    "pytest": {"version": "==7.1.2"}
  }
}`
	got := pkgMap(parsePipfileLock(lock))
	want := map[string]string{
		"flask":    "2.0.1",
		"requests": "2.28.1",
		"pytest":   "7.1.2", // dev deps included — they ship in CI images
	}
	if len(got) != len(want) {
		t.Fatalf("want %d packages, got %d: %+v", len(want), len(got), got)
	}
	for n, v := range want {
		if got[n] != v {
			t.Errorf("%s: want %s got %s", n, v, got[n])
		}
	}
}

func TestParsePipfileLock_SkipsUnpinnedAndGarbage(t *testing.T) {
	const lock = `{
  "default": {
    "ok": {"version": "==1.0.0"},
    "noversion": {"hashes": ["sha256:x"]}
  }
}`
	pkgs := parsePipfileLock(lock)
	if len(pkgs) != 1 || pkgs[0].name != "ok" {
		t.Fatalf("only the pinned dep should parse, got %+v", pkgs)
	}
	if got := parsePipfileLock("not json"); got != nil {
		t.Errorf("invalid JSON should yield nil, got %+v", got)
	}
}

func TestParseManifest_DispatchesByName(t *testing.T) {
	cases := []struct {
		path    string
		content string
		want    int
	}{
		{"poetry.lock", "[[package]]\nname=\"a\"\nversion=\"1.0\"\n", 1},
		{"sub/Pipfile.lock", `{"default":{"a":{"version":"==1.0"}}}`, 1},
		{"requirements.txt", "a==1.0\nb==2.0\n", 2},
	}
	for _, c := range cases {
		got := parseManifest(c.path, c.content)
		if len(got) != c.want {
			t.Errorf("%s: want %d pkgs, got %d (%+v)", c.path, c.want, len(got), got)
		}
	}
}

func TestIsPythonManifest(t *testing.T) {
	yes := []string{"requirements.txt", "poetry.lock", "Pipfile.lock"}
	no := []string{"package.json", "go.mod", "Pipfile", "pyproject.toml", "requirements.in"}
	for _, n := range yes {
		if !isPythonManifest(n) {
			t.Errorf("%s should be recognised as a Python manifest", n)
		}
	}
	for _, n := range no {
		if isPythonManifest(n) {
			t.Errorf("%s should NOT be a Python manifest the pip scanner parses", n)
		}
	}
}

// sanity: parsed packages are returned in a deterministic order after the
// scanner's sort, so multi-manifest output is stable.
func TestParsePoetryLock_OrderIsCallerSorted(t *testing.T) {
	got := parsePoetryLock("[[package]]\nname=\"z\"\nversion=\"1\"\n[[package]]\nname=\"a\"\nversion=\"2\"\n")
	names := []string{got[0].name, got[1].name}
	// parsePoetryLock preserves file order (z then a); the scanner sorts
	// findings by ID downstream, so we only assert both were captured.
	sort.Strings(names)
	if names[0] != "a" || names[1] != "z" {
		t.Errorf("expected both a and z captured, got %+v", got)
	}
}
